package ru.neverland.townyenvironment.integration;
import java.util.*;
import java.math.BigDecimal;
import ru.neverland.core.ApiServices;
import ru.neverland.townyenvironment.model.DistrictEnvironment;
/** Physical assignment from the same Districts format-2 snapshot; no Towny block reads. */
public final class DistrictEnvironmentBridge {
    public record Snapshot(boolean available,boolean pending,String issue,long sourceAt,Map<String,DistrictEnvironment.District> districts,Map<String,String> assignments){public Snapshot{districts=Map.copyOf(districts);assignments=Map.copyOf(assignments);}}
    private static Snapshot missing(String text,boolean pending){return new Snapshot(false,pending,text,0,Map.of(),Map.of());}
    public Snapshot read(UUID town,long now){try{var api=ApiServices.connect("NeverLandTownyDistricts","ru.neverland.townydistricts.api.TownyDistrictsApi",1,"assessment");if(api.state()==ApiServices.State.NOT_INSTALLED)return new Snapshot(true,false,"",now,Map.of(),Map.of());if(!api.ready())return missing("Сведения о районах временно недоступны",false);return decode(api.invoke("assessment",new Class<?>[]{UUID.class},town),now);}catch(ReflectiveOperationException|RuntimeException|LinkageError error){return missing("Не удалось проверить районы; городские показатели сохранены",false);}}
    public static Snapshot decode(Object raw,long now){var data=map(raw,32);boolean available=flag(data,"available"),pending=flag(data,"pending");if(!available)return missing(pending?"Сведения о районах готовятся":"Оценка районов временно отключена",pending);if(pending||integer(data.get("format"))!=2)throw new IllegalArgumentException("Нужен формат районов 2");long source=integer(data.get("sourceAt")),checked=integer(data.get("checkedAt"));if(source<1||checked<1||source>now||checked>now||now-source>60_000)return missing("Сведения о районах ожидают обновления",true);var districts=new HashMap<String,DistrictEnvironment.District>();for(var e:map(data.get("rows"),128).entrySet()){var row=map(e.getValue(),32);String id=text(e.getKey());if(!id.equals(text(row.get("id"))))throw new IllegalArgumentException("Не совпадает район");if(!flag(row,"buildingsAvailable")||!flag(row,"worldAvailable"))return missing("Площадки района временно недоступны",true);districts.put(id,new DistrictEnvironment.District(id,text(row.get("name"))));}var assignments=new HashMap<String,String>();for(var e:map(data.get("assignments"),1024).entrySet()){String project=text(e.getKey()),district=text(e.getValue());if(!project.matches("[a-z][a-z0-9_]{0,63}")||!districts.containsKey(district))throw new IllegalArgumentException("Неверная площадка");assignments.put(project,district);}return new Snapshot(true,false,"",source,districts,assignments);}
    private static Map<?,?> map(Object raw,int maximum){if(!(raw instanceof Map<?,?> map)||map.size()>maximum)throw new IllegalArgumentException("Неверный снимок района");return map;}private static String text(Object raw){if(!(raw instanceof String s)||s.isBlank()||s.length()>160)throw new IllegalArgumentException("Неверная строка района");return s;}private static boolean flag(Map<?,?> map,String key){if(!(map.get(key)instanceof Boolean flag))throw new IllegalArgumentException("Неверный флаг района");return flag;}private static long integer(Object raw){if(!(raw instanceof Number n))throw new IllegalArgumentException("Неверное число района");return new BigDecimal(n.toString()).longValueExact();}
}
